define("quiz_livemonitor/monitor", ["core/ajax", "core/templates", "core/notification", "core/str"], function(Ajax, Templates, Notification, Str) {
    "use strict";

    var SELECTORS = {
        region: '[data-region="livemonitor-body"]',
        toggle: '[data-action="livemonitor-toggle"]',
        refresh: '[data-action="livemonitor-refresh"]'
    };

    var cmid = null;
    var intervalMs = 20000;
    var timer = null;
    var paused = false;
    var inflight = false;

    var refresh = function() {
        if (inflight) {
            return;
        }
        var region = document.querySelector(SELECTORS.region);
        if (!region) {
            return;
        }
        inflight = true;
        Ajax.call([{
            methodname: "quiz_livemonitor_get_progress",
            args: {cmid: cmid}
        }])[0].then(function(response) {
            return Templates.renderForPromise("quiz_livemonitor/monitor_body", response);
        }).then(function(result) {
            Templates.replaceNodeContents(region, result.html, result.js);
            inflight = false;
            return null;
        }).catch(function(error) {
            inflight = false;
            Notification.exception(error);
        });
    };

    var togglePause = function(button) {
        paused = !paused;
        Str.get_string(paused ? "resume" : "pause", "quiz_livemonitor").then(function(label) {
            button.textContent = label;
            return null;
        }).catch(Notification.exception);
        if (!paused) {
            refresh();
        }
    };

    return {
        init: function(cmidParam, intervalSeconds) {
            cmid = parseInt(cmidParam, 10);
            intervalMs = Math.max(5, parseInt(intervalSeconds, 10) || 20) * 1000;

            document.addEventListener("click", function(e) {
                var toggle = e.target.closest(SELECTORS.toggle);
                if (toggle) {
                    e.preventDefault();
                    togglePause(toggle);
                    return;
                }
                var refreshBtn = e.target.closest(SELECTORS.refresh);
                if (refreshBtn) {
                    e.preventDefault();
                    refresh();
                }
            });

            timer = setInterval(function() {
                if (!paused && !document.hidden) {
                    refresh();
                }
            }, intervalMs);
        }
    };
});
